}

credential_suffixes := ["_password", "_secret", "_token", "_key", "_credential", "_user", "_username"]

is_credential_field(name) {
    lower_name := lower(name)
    credential_fields[lower_name]
} else {
    lower_name := lower(name)
    field := credential_fields[_]
    ends_with(lower_name, concat("", ["_", field]))
} else {
    lower_name := lower(name)
    suffix := credential_suffixes[_]
    ends_with(lower_name, suffix)
}

