is_path_or_dn(value) {
    startswith(value, "/")
} else {
    startswith(value, "cn=")
} else {
    startswith(value, "uid=")
} else {
    startswith(value, "ou=")
} else {
    startswith(value, "dc=")
} else {
    startswith(value, "o=")
} else {
    startswith(value, "ldaps://")
} else {
    startswith(value, "ldap://")
} else {
    regex.match("^[a-z]+://", value)
}

is_short_common_word(value) {
    lower_val := lower(value)
    lower_val == "true"
} else {
    lower_val := lower(value)
    lower_val == "false"
