    lower_val == "password"
}

looks_like_secret_manager_ref(value) {
    regex.match("^(var|data|module|local|each|path|terraform|aws_secretsmanager|azurerm_key_vault|vault_|lookup)\\.", value)
} else {
    regex.match("^\\$\\{", value)
